#!/usr/bin/env python3
"""Execute na raiz do projeto: python3 adicionar-ofersul.py"""
from pathlib import Path
import base64, json, re, shutil, subprocess, tempfile
from datetime import datetime
PAYLOAD = {'public/assets/ofersul-logo.jpg': '', 'public/encartes/ofersul/pagina-01.jpg': '', 'public/encartes/ofersul/pagina-02.jpg': '', 'public/ofersul.css': ''}
root=Path.cwd()
app_path=root/'public/app.js'
if not app_path.is_file():
    raise SystemExit('Abra o terminal na pasta do projeto que contem public/app.js.')
app=app_path.read_text()
if '// ofersul-card-v1' in app:
    original=app
    app=app.replace("=>!store.validFrom||", "=>store.id==='ofersul'||!store.validFrom||",1)
    app=app.replace("validityLabel:'Válido em 21/09/2026 · Enquanto durarem os estoques'", "validityLabel:'Encarte de teste · Ofertas originalmente válidas em 21/09/2026'",1)
    if app==original:
        print('Card de teste ja atualizado. Nenhuma alteracao repetida.')
        raise SystemExit(0)
    with tempfile.TemporaryDirectory() as tmp:
        check=Path(tmp)/'app.mjs';check.write_text(app)
        subprocess.run(['node','--check',str(check)],check=True)
    sw_path=root/'public/sw.js'
    sw=sw_path.read_text()
    sw,n=re.subn(r"(const CACHE\s*=\s*['\"])([^'\"]+)",lambda m:m[1]+m[2]+'-ofersul-teste-v2',sw,count=1)
    if n!=1:raise SystemExit('Cache nao reconhecido. Nenhum arquivo alterado.')
    backup=root/'.ofersul-backup'/datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    backup.mkdir(parents=True,exist_ok=True)
    shutil.copy2(app_path,backup/'app.js');shutil.copy2(sw_path,backup/'sw.js')
    app_path.write_text(app);sw_path.write_text(sw)
    print('Ofersul ajustado: encarte de teste permanece visivel apos a validade.')
    raise SystemExit(0)
def replace_once(text,old,new):
    if text.count(old)!=1:
        raise SystemExit('A estrutura do projeto mudou. Nenhum arquivo foi alterado. Envie o public/app.js atualizado.')
    return text.replace(old,new,1)
app=replace_once(app,'let favorites = []',"""// ofersul-card-v1
stores.push({
  id:'ofersul', name:'Ofersul Supermercados',
  logo:'/assets/ofersul-logo.jpg',
  validFrom:'2026-09-21', validUntil:'2026-09-21',
  validityLabel:'Encarte de teste · Ofertas originalmente válidas em 21/09/2026',
  pages:['/encartes/ofersul/pagina-01.jpg','/encartes/ofersul/pagina-02.jpg'],
  branches:[{neighborhood:'Ouro Branco',address:'Rua Bento Gonçalves, 335, Ouro Branco - Novo Hamburgo'}]
})
const flyerDateToday=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date())
const flyerIsCurrent=(store,today=flyerDateToday())=>store.id==='ofersul'||!store.validFrom||(!store.validUntil?today>=store.validFrom:today>=store.validFrom&&today<=store.validUntil)
for(const store of stores) for(const branch of store.branches||[]) {
  if(![...neighborhood.options].some(option=>option.value===branch.neighborhood)) {
    const option=document.createElement('option');option.value=branch.neighborhood;option.textContent=branch.neighborhood;neighborhood.append(option)
  }
}
let favorites = []""")
app=replace_once(app,'function validityFor(store) {','function validityFor(store) {\n  if(store.validityLabel)return store.validityLabel')
app=replace_once(app,"const visible=stores.filter(s=>neighborhood.value==='all'||s.neighborhood===neighborhood.value||s.branches?.some(b=>b.neighborhood===neighborhood.value))","const visible=stores.filter(s=>flyerIsCurrent(s)&&(neighborhood.value==='all'||s.neighborhood===neighborhood.value||s.branches?.some(b=>b.neighborhood===neighborhood.value)))")
app=replace_once(app,"if(option.value!=='all' && !offers.some(item=>item.neighborhoods.includes(option.value))) option.remove()","if(option.value!=='all' && !offers.some(item=>item.neighborhoods.includes(option.value)) && !stores.some(store=>store.neighborhood===option.value||store.branches?.some(branch=>branch.neighborhood===option.value))) option.remove()")
app+="""
// Atualiza a validade na virada do dia, inclusive ao retornar ao aplicativo.
let lastFlyerDate=flyerDateToday()
function refreshFlyerDate(){
  const today=flyerDateToday()
  if(today!==lastFlyerDate){lastFlyerDate=today;render()}
}
setInterval(refreshFlyerDate,1000)
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshFlyerDate()})
window.addEventListener('pageshow',refreshFlyerDate)
"""
index_path=root/'public/index.html'
html=index_path.read_text()
html=replace_once(html,'</head>','<link rel="stylesheet" href="/ofersul.css">\n</head>')
sw_path=root/'public/sw.js'
sw=sw_path.read_text()
sw,n=re.subn(r"(const CACHE\s*=\s*['\"])([^'\"]+)",lambda m:m[1]+m[2]+'-ofersul-card-v1',sw,count=1)
if n!=1:raise SystemExit('Cache nao reconhecido. Nenhum arquivo alterado.')
with tempfile.TemporaryDirectory() as tmp:
    check=Path(tmp)/'app.mjs';check.write_text(app)
    subprocess.run(['node','--check',str(check)],check=True)
outputs={root/name:base64.b64decode(data) for name,data in PAYLOAD.items()}
outputs.update({app_path:app.encode(),index_path:html.encode(),sw_path:sw.encode()})
backup=root/'.ofersul-backup'/datetime.now().strftime('%Y%m%d-%H%M%S-%f')
for path in outputs:
    if path.exists():
        target=backup/path.relative_to(root);target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,target)
for path,data in outputs.items():
    path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
print('Ofersul incluido: duas paginas, zoom, favoritos, compartilhamento e rota para Rua Bento Goncalves, 335.')
print('Encarte de teste: permanece visivel apos 21/09/2026, com a data original identificada.')
print('Backup dos arquivos alterados: '+str(backup))
